function shortOf(name: string) {
  return name.split(/\s+/).slice(0, 2).map((w) => w.charAt(0)).join("");
}

export function buildCatalogGroups(): FactoryGroup[] {
  const map = new Map<string, FactoryGroup>();
  for (const r of catalogRows) {
    let g = map.get(r.factory);
    if (!g) {
      g = { factory: r.factory, shortName: shortOf(r.factory), updatedAgo: "طبق فایل فنی", totalStock: "—", totalChange: 0, delivery: "به‌زودی اعلام می‌شود", rows: [] };
      map.set(r.factory, g);
    }
    const row: PriceRow = { name: r.product, size: r.size, weight: r.weight, price: 0, change: 0, stock: "نامشخص", aiPrediction: "ثابت", spark: [1, 1] };
    g.rows.push(row);
  }
  return Array.from(map.values());
}
